class PruebasEnlaces {static int Main(){try{string real="https://example.org/foto.jpg?x=1&y=2";if(ImagenRemota.Normalizar("https://www.google.com/imgres?imgurl="+Uri.EscapeDataString(real))!=real)throw new Exception("Google no normalizado");if(ImagenRemota.Normalizar(real)!=real)throw new Exception("Enlace directo alterado");bool rechazo=false;try{ImagenRemota.Normalizar("file:///C:/foto.jpg");}catch(ArgumentException){rechazo=true;}if(!rechazo)throw new Exception("Esquema incorrecto aceptado");Console.WriteLine("OK: enlace Google, consulta original y rechazo de rutas no HTTP.");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}
